const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const read=k=>{try{return localStorage.getItem(k)}catch{return null}},save=(k,v)=>{try{localStorage.setItem(k,v)}catch{}};
const query=new URLSearchParams(location.search),supported=Object.keys(copy),browserLanguage=(navigator.languages||[navigator.language]).map(v=>v.split('-')[0]).map(v=>v==='ku'?'kmr':v).find(v=>supported.includes(v));
let locale=query.get('lang')||read('dicle-language')||browserLanguage||'en';if(!supported.includes(locale))locale='en';
let currentView='home',size='compact',fill='foam',basket=[],rotated=false,favourite=read('dicle-favourite')==='yes',theme=query.get('theme')||read('dicle-theme')||'system',toastTimer;
const t=k=>copy[locale][k]||copy.en[k]||k,dimensions=()=>size==='compact'?180:240,price=()=>fill==='foam'?(size==='compact'?349:449):(size==='compact'?189:249),money=v=>new Intl.NumberFormat(locale==='kmr'?'en':locale,{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v);
function applyTheme(){document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;$('#theme').value=theme}
function applyLanguage(){document.documentElement.lang=locale==='kmr'?'ku-Latn':locale;document.documentElement.dir=locale==='ar'?'rtl':'ltr';$('#language').value=locale;$$('[data-i]').forEach(el=>{el.innerHTML=t(el.dataset.i)});updateProduct();updatePlanner();renderBasket();$('#product-image-label').textContent=t($('.product-visual').classList.contains('reference')?'referenceNote':'imageNote');decorateIcons();}
function view(v,scroll=true){if(!['home','product','planner','admin'].includes(v))v='home';currentView=v;document.body.dataset.view=v;$$('.view').forEach(el=>el.hidden=el.id!==v+'-view');$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='admin')renderAdmin('overview');if(v==='planner')updatePlanner();if(scroll)window.scrollTo({top:0,behavior:'instant'});history.replaceState(null,'','#'+v);}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3200)}
function updateProduct(){const summary=t(fill==='foam'?'foamSummary':'coversSummary');$('#product-price').textContent=money(price());$('#bundle-summary').textContent=summary;$('#included-copy').textContent=summary;$('#support-summary').textContent=`${t('setName')} · ${dimensions()} × 70 cm · ${t(fill==='foam'?'withFoam':'coversOnly')}`;$('#favourite').innerHTML=icon('heart');$('#favourite').classList.toggle('is-saved',favourite);$('#favourite').setAttribute('aria-pressed',String(favourite));$('#planner-size').value=size;}
function updatePlanner(){const width=Number($('#room-width').value),depth=Number($('#room-depth').value),w=rotated?70:dimensions(),d=rotated?dimensions():70;$('#width-output').textContent=width+' cm';$('#depth-output').textContent=depth+' cm';$('#plan-dim').textContent=width+' × '+depth+' cm';$('#room-plan').style.aspectRatio=width+'/'+depth;$('#room-plan').style.width=Math.min(100,width/depth*100)+'%';$('#footprint').style.width=(w/width*100)+'%';$('#footprint').style.height=(d/depth*100)+'%';$('#footprint-label').textContent=w+' × '+d+' cm';const fits=w<=width&&d<=depth;$('#fit-result').classList.toggle('no-fit',!fits);$('#fit-result').textContent=t(fits?'fits':'noFit')+(fits?' '+t('clearance')+': '+(width-w)+' × '+(depth-d)+' cm.':'');}
function renderBasket(){const content=$('#basket-content');content.replaceChildren();$('#bag-count').textContent=basket.length;if(!basket.length){const p=document.createElement('p');p.className='dialog-empty';p.textContent=t('empty');content.append(p);return}basket.forEach((item,index)=>{const row=document.createElement('div');row.className='basket-item';const img=document.createElement('img');img.src='assets/courtyard-v2.png';img.alt=t('imageNote');const info=document.createElement('div'),strong=document.createElement('strong'),p=document.createElement('p'),remove=document.createElement('button');strong.textContent=t('setName');p.textContent=`${item.width} × 70 cm · ${t(item.fill==='foam'?'withFoam':'coversOnly')} · ${money(item.price)}`;remove.className='text-button';remove.textContent=t('remove');remove.onclick=()=>{basket.splice(index,1);renderBasket()};info.append(strong,p,remove);row.append(img,info);content.append(row)});const total=document.createElement('div');total.className='basket-total';const label=document.createElement('span'),value=document.createElement('strong');label.textContent=t('total');value.textContent=money(basket.reduce((s,i)=>s+i.price,0));total.append(label,value);const note=document.createElement('p');note.className='quiet';note.textContent=t('checkoutNote');content.append(total,note);}
$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$$('[data-story]').forEach(b=>b.onclick=()=>{view('home',false);$('#story').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})});$$('[data-cart]').forEach(b=>b.onclick=()=>$('#basket').showModal());$$('[data-support]').forEach(b=>b.onclick=()=>$('#support').showModal());$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());
$('#language').onchange=e=>{locale=e.target.value;save('dicle-language',locale);applyLanguage()};$('#theme').onchange=e=>{theme=e.target.value;save('dicle-theme',theme);applyTheme()};matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(theme==='system')applyTheme()});
$$('input[name=size]').forEach(input=>input.onchange=()=>{size=input.value;updateProduct();updatePlanner()});$$('input[name=fill]').forEach(input=>input.onchange=()=>{fill=input.value;updateProduct()});$('#add-basket').onclick=()=>{basket.push({width:dimensions(),fill,price:price()});renderBasket();$('#basket').showModal()};$('#favourite').onclick=()=>{favourite=!favourite;save('dicle-favourite',favourite?'yes':'no');updateProduct();toast(t(favourite?'saved':'unsaved'))};
function gallery(reference){$('.product-visual').classList.toggle('reference',reference);$('#product-image').src='assets/'+(reference?'reference-only.jpg':'courtyard-v2.png');$('#product-image').alt=t(reference?'referenceNote':'imageNote');$('#product-image-label').textContent=t(reference?'referenceNote':'imageNote');$('#reference-image').classList.toggle('active',reference);$('#room-image').classList.toggle('active',!reference)}$('#reference-image').onclick=()=>gallery(true);$('#room-image').onclick=()=>gallery(false);
$('#room-width').oninput=updatePlanner;$('#room-depth').oninput=updatePlanner;$('#planner-size').onchange=e=>{size=e.target.value;$$('input[name=size]').forEach(i=>i.checked=i.value===size);updateProduct();updatePlanner()};$('#rotate').onclick=()=>{rotated=!rotated;updatePlanner()};
const orderRows=[['D-1048','Netherlands','With foam','€349','Ready to pack','ready'],['D-1047','Germany','Covers only','€189','Awaiting payment','attention'],['D-1046','France','With foam','€449','Dispatched',''],['D-1045','Belgium','Covers only','€249','Return requested','attention']];
const ordersTable=()=>`<table><thead><tr><th>Order</th><th>Destination</th><th>Configuration</th><th>Total*</th><th>Status</th><th></th></tr></thead><tbody>${orderRows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td><span class="status ${r[5]}">${r[4]}</span></td><td><button class="text-button" data-order="${r[0]}">View</button></td></tr>`).join('')}</tbody></table><p class="quiet">*Illustrative goods totals. These are fictional orders.</p>`;
const adminTitles={overview:'A little order. More time for people.',orders:'Orders',inventory:'Inventory',messages:'Customer messages',customers:'Customers',discounts:'Discounts',reviews:'Feedback & reviews',health:'App health & logs'};
function renderAdmin(tab){$$('[data-admin]').forEach(b=>b.classList.toggle('active',b.dataset.admin===tab));const main=$('#admin-main');main.innerHTML=`<div class="admin-top"><div><h1>${adminTitles[tab]}</h1><p>Piwas shop · Netherlands warehouse · EU destinations</p></div><span class="demo-pill">Demo data</span></div>`;
if(tab==='overview')main.innerHTML+=`<div class="metrics"><div class="metric"><span>Ready to pack</span><strong>1</strong><small>Paid and stock allocated</small></div><div class="metric"><span>Needs your attention</span><strong>2</strong><small>A return and a payment</small></div><div class="metric"><span>Units available</span><strong>18</strong><small>After active reservations</small></div></div><div class="admin-panel"><h2>Today’s work</h2><div class="admin-action"><div><strong>Prepare D-1048 for collection</strong><p>Compact set · with foam · Netherlands</p></div><button data-admin-link="orders">View order</button></div><div class="admin-action"><div><strong>Review the return request</strong><p>D-1045 · covers only · Belgium</p></div><button data-admin-link="orders">Review return</button></div><div class="admin-action"><div><strong>Reply to 2 product questions</strong><p>Foam firmness and delivery access</p></div><button data-admin-link="messages">Open inbox</button></div></div><div class="admin-panel"><h2>Recent orders</h2>${ordersTable()}</div>`;
if(tab==='orders')main.innerHTML+=`<label><span class="sr-only">Find a sample order</span><input class="search-input" id="order-search" placeholder="Find order D-1048…"></label><div class="admin-panel">${ordersTable()}<div id="order-detail"></div></div>`;
if(tab==='inventory')main.innerHTML+=`<div class="admin-notice">Available stock = physical stock − reservations − allocated orders − quarantine. Sample figures below are illustrative.</div><div class="admin-panel"><h2>Seating stock</h2><table><thead><tr><th>Stock item</th><th>Physical</th><th>Reserved</th><th>Allocated</th><th>Available</th></tr></thead><tbody><tr><td>Compact cover kit</td><td>12</td><td>2</td><td>1</td><td>9</td></tr><tr><td>Generous cover kit</td><td>11</td><td>1</td><td>1</td><td>9</td></tr><tr><td>Compact foam kit</td><td>8</td><td>1</td><td>1</td><td>6</td></tr><tr><td>Generous foam kit</td><td>5</td><td>0</td><td>1</td><td>4</td></tr></tbody></table><p class="quiet">Filled sets consume a cover kit AND a foam kit. Their stock is not counted twice.</p></div>`;
if(tab==='messages')main.innerHTML+=`<div class="admin-panel"><h2>Waiting for a reply</h2><div class="admin-action"><div><strong>How firm is the foam?</strong><p>Product question · Compact · Dutch · 2 hours ago</p></div><button data-demo="The full inbox will support replies, attachments, internal notes and order links.">Open message</button></div><div class="admin-action"><div><strong>Can this be delivered upstairs?</strong><p>Delivery question · Generous · German · 4 hours ago</p></div><button data-demo="Delivery promises must be checked against the carrier service before replying.">Open message</button></div></div>`;
if(tab==='customers')main.innerHTML+=`<div class="admin-panel"><h2>Customer directory</h2><p>Search by order or customer reference. Customer details appear only to authorised roles.</p><table><thead><tr><th>Customer</th><th>Locale</th><th>Orders</th><th>Saved items</th><th>Newsletter</th></tr></thead><tbody><tr><td>Demo customer 01</td><td>Nederlands</td><td>1</td><td>2</td><td>Not subscribed</td></tr><tr><td>Demo customer 02</td><td>Deutsch</td><td>1</td><td>1</td><td>Subscribed</td></tr></tbody></table></div>`;
if(tab==='discounts')main.innerHTML+=`<div class="admin-panel"><h2>Special offers</h2><div class="admin-action"><div><strong>WELCOME10 · draft</strong><p>10% · one redemption per customer · not active</p></div><button data-demo="A finished discount editor will set eligibility, dates, limits and stacking rules. No discount was created.">Preview rules</button></div><p>Public promotions use verified price history. A crossed-out price must never be invented.</p></div>`;
if(tab==='reviews')main.innerHTML+=`<div class="admin-panel"><h2>Three different signals</h2><div class="admin-action"><div><strong>Product reviews</strong><p>Invited after delivery. Linked to the purchased configuration.</p></div><span class="status">No reviews yet</span></div><div class="admin-action"><div><strong>Customer support feedback</strong><p>Asked after a support case closes. Separate from product ratings.</p></div><span class="status">Private by default</span></div><div class="admin-action"><div><strong>Website feedback</strong><p>Optional, unobtrusive and never interrupts payment.</p></div><span class="status">Product insights</span></div><p class="quiet">No fabricated stars, testimonials or customer counts in this concept.</p></div>`;
if(tab==='health')main.innerHTML+=`<div class="admin-notice">Illustrative health view. Owner access only. No production logs or system connection.</div><div class="admin-panel"><h2>Operations</h2><table><thead><tr><th>Service</th><th>State</th><th>Detail</th></tr></thead><tbody><tr><td>Payments</td><td><span class="status">Not connected</span></td><td>New Mollie website profile required</td></tr><tr><td>Email</td><td><span class="status">Not connected</span></td><td>Sender domain to verify</td></tr><tr><td>Inventory</td><td><span class="status">Demo only</span></td><td>No warehouse integration</td></tr></tbody></table></div><div class="admin-panel"><h2>Safe diagnostics</h2><p>Release version, correlation IDs, failed jobs and payment reconciliation. Redacted logs; no passwords, payment credentials or room photographs. Audited retry actions, with no shell or SQL console in the admin.</p></div>`;
main.querySelectorAll('[data-admin-link]').forEach(b=>b.onclick=()=>renderAdmin(b.dataset.adminLink));main.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>toast(b.dataset.demo));main.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{if(tab!=='orders'){renderAdmin('orders')}const item=orderRows.find(r=>r[0]===b.dataset.order);$('#order-detail').innerHTML=`<div class="admin-row-details"><strong>${item[0]} · ${item[4]}</strong><br>${item[1]} · ${item[2]} · ${item[3]} sample goods total<br>Timeline, delivery details, packing, cancellation and refund actions will appear here with role checks and an audit trail.</div>`});const search=$('#order-search');if(search)search.oninput=()=>{const q=search.value.toLowerCase();main.querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))};}
$$('[data-admin]').forEach(b=>b.onclick=()=>renderAdmin(b.dataset.admin));applyTheme();applyLanguage();view(location.hash.slice(1)||'home',false);
